-- More researched menu prices (PLAN 11.3), gathered 2026-11-13 by reading each source_url page
-- (mostly Glovo Timisoara store pages; never estimated). Delivery-app prices are often higher than
-- in the shop; promo prices are in note. Left out: "Antalya" and "Sultan Shawarma" on Glovo may not be
-- our "Antalya Fast Food" / "Sultan".
-- Also marks chain prices that were read on another city's listing (search_places shows a caution).

update public.place_prices set note = 'OTHER CITY: ' || note
where place_name in ('Ted''s Coffee Co.', 'Tucano Coffee Mexico', 'Tucano Coffee Thailand', 'Tucano Coffee Venezuela')
  and note not like 'OTHER CITY:%';

